css:
.tpl-simple-example { font-family: 'Cairo', sans-serif; color: #111; }
.tpl-simple-example .doc { border: 2px solid var(--c-primary); border-radius: 8px; display: flex; flex-direction: column; position: relative; padding: 14px; }
.tpl-simple-example .top { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid var(--c-primary); padding-bottom: 10px; }
.tpl-simple-example .top h1 { margin: 0; color: var(--c-primary); font-size: 26px; }
.tpl-simple-example .top .logo-img { max-height: 70px; }
.tpl-simple-example .top .logo-symbol { font: 900 30px serif; color: var(--c-primary); }
.tpl-simple-example .top .logo-sub { font-size: 10px; letter-spacing: 2px; }
.tpl-simple-example .meta { display: flex; justify-content: space-between; margin: 10px 0; font-weight: 700; }
.tpl-simple-example table { width: 100%; border-collapse: collapse; font-size: 13px; }
.tpl-simple-example th { background: var(--c-primary); color: #fff; padding: 6px; }
.tpl-simple-example td { border: 1px solid #ccc; padding: 4px 6px; text-align: center; height: 24px; }
.tpl-simple-example .sum { margin-top: auto; display: flex; justify-content: space-between; align-items: flex-end; padding-top: 12px; font-weight: 700; }
.tpl-simple-example .sum table { width: 240px; }
